<?php require_once __DIR__ . '/../cdn.php'; \SimpleCdn\Cdn::enable([]); $purgeLogs = \SimpleCdn\Cdn::getPurgeLogRecent(100); $purgeToday = \SimpleCdn\Cdn::getPurgeLogToday(); ?> <!DOCTYPE html> <html lang="zh-CN"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Simple CDN 后台 - 清理日志审计</title> <style> * { box-sizing: border-box; } body { font-family: system-ui, -apple-system, Segoe UI, Microsoft YaHei, sans-serif; background: #f5f7fa; color: #111; margin: 0; } .topbar { background: #fff; border-bottom: 1px solid #e2e8f0; padding: 12px 24px; display: flex; align-items: center; gap: 16px; } .topbar h1 { font-size: 16px; margin: 0; color: #0f172a; } .topbar a { color: #2563eb; text-decoration: none; font-size: 13px; } .topbar a:hover { text-decoration: underline; } .topbar .spacer { flex: 1; } .container { max-width: 1200px; margin: 24px auto; padding: 0 20px; } .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 24px; } .stat-card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 16px; } .stat-card .value { font-size: 30px; font-weight: 700; } .stat-card .label { font-size: 13px; color: #64748b; margin-top: 4px; } .card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 20px; } .card h2 { font-size: 18px; margin: 0 0 16px; color: #0f172a; } .btn { display: inline-block; padding: 8px 14px; border: none; border-radius: 6px; font-size: 13px; cursor: pointer; text-decoration: none; } .btn:hover { opacity: 0.9; } .btn-secondary { background: #f1f5f9; color: #334155; } .btn-secondary:hover { background: #e2e8f0; } .btn-sm { padding: 4px 8px; font-size: 12px; } .table { width: 100%; border-collapse: collapse; margin-top: 12px; } .table th { text-align: left; padding: 10px 12px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9; background: #fafbfc; } .table td { padding: 10px 12px; border-bottom: 1px solid #f1f5f9; font-size: 14px; } .table tr:hover { background: #f8fafc; } .badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 700; } .badge-admin { background: #dbeafe; color: #1e40af; } .badge-remote { background: #fde047; color: #713f12; } .badge-success { background: #dcfce7; color: #166534; } .badge-fail { background: #fee2e2; color: #991b1b; } .badge-skipped { background: #f1f5f9; color: #64748b; } .muted { color: #64748b; font-size: 13px; } .empty { color: #94a3b8; font-style: italic; } .token { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 11px; background: #f1f5f9; padding: 1px 6px; border-radius: 4px; } .node-tag { display: inline-block; padding: 1px 6px; background: #e2e8f0; border-radius: 4px; font-size: 11px; margin: 1px; } .msg { padding: 10px 16px; border-radius: 6px; margin-bottom: 16px; font-size: 14px; } .msg.ok { background: #dcfce7; color: #166534; border: 1px solid #86efac; } .msg.warn { background: #fef3c7; color: #92400e; border: 1px solid #fde68a; } </style> </head> <body> <div class="topbar"> <h1>清理日志审计</h1> <div class="spacer"></div> <div class="btn-group" style="display:flex;gap:8px;"> <a href="action.php?do=purge_log_export&format=csv" class="btn btn-secondary btn-sm">导出CSV</a> <a href="action.php?do=purge_log_export&format=json" class="btn btn-secondary btn-sm">导出JSON</a> </div> <a href="index.php" class="btn-secondary">← 返回仪表盘</a> </div> <div class="container"> <div class="grid"> <div class="stat-card"> <div class="value">echo number_format($purgeToday['total']); ?></div> <div class="label">今日清理次数</div> </div> <div class="stat-card"> <div class="value">echo number_format($purgeToday['deleted']); ?></div> <div class="label">今日删除文件数</div> </div> <div class="stat-card"> <div class="value badge-success">echo number_format($purgeToday['success']); ?></div> <div class="label">节点清理成功</div> </div> <div class="stat-card"> <div class="value badge-fail">echo number_format($purgeToday['failed']); ?></div> <div class="label">节点清理失败</div> </div> </div> <div class="card"> <h2>清理历史记录（最近 100 条）</h2> if (empty($purgeLogs)): ?> <p class="empty">暂无清理日志记录。</p> else: ?> <table class="table"> <thead> <tr> <th style="width:16%;">时间</th> <th style="width:12%;">操作者</th> <th style="width:14%;">范围</th> <th style="width:10%;">主站删除</th> <th style="width:14%;">令牌</th> <th style="width:auto;">节点详情</th> </tr> </thead> <tbody> foreach ($purgeLogs as $log): ?> <tr> <td>echo htmlspecialchars($log['time'] ?? ''); ?></td> <td> <span class="badge echo $log['operator'] === 'admin' ? 'badge-admin' : 'badge-remote'; ?>"> echo $log['operator'] === 'admin' ? '后台' : '远程API'; ?> </span> </td> <td> <span class="badge echo $log['scope'] === 'all_nodes' ? 'badge-success' : 'badge-remote'; ?>"> $scopeMap = ['local' => '仅主站', 'all_nodes' => '全部节点']; echo $scopeMap[$log['scope'] ?? ''] ?? $log['scope'] ?? ''; ?> </span> </td> <td>echo number_format($log['deleted'] ?? 0); ?></td> <td><span class="token">echo htmlspecialchars($log['token_used'] ?? ''); ?></span></td> <td> $nodes = $log['nodes'] ?? []; if (empty($nodes)) { echo '<span class="muted">无节点数据</span>'; } else { foreach ($nodes as $n) { $statusClass = $n['status'] === 'success' ? 'badge-success' : ($n['status'] === 'failed' ? 'badge-fail' : 'badge-skipped'); echo '<span class="badge ' . $statusClass . '">' . htmlspecialchars($n['status'] ?? '') . '</span>'; echo '<span class="node-tag">' . htmlspecialchars($n['id'] ?? '') . '</span>'; if (!empty($n['message'])) { echo '<br><span class="muted" style="font-size:11px;">' . htmlspecialchars($n['message']) . '</span>'; } } } ?> </td> </tr> endforeach; ?> </tbody> </table> endif; ?> </div> <div class="card"> <h2>审计说明</h2> <div class="muted"> <ul style="margin:0; padding-left:20px;"> <li><strong>操作者</strong>：后台（admin）或远程 API（remote_api）触发的清理操作。</li> <li><strong>范围</strong>：仅主站（local）或全部节点（all_nodes）。</li> <li><strong>令牌</strong>：远程 API 调用时的 purge_token 已脱敏，仅显示后4位。</li> <li><strong>节点状态</strong>：success=清理成功，failed=清理失败，skipped=跳过（离线或当前节点）。</li> <li>日志按日期保存在 <code>purge_logs/</code> 目录，最多保留最近 500 条，无需数据库。</li> </ul> </div> </div> </div> </body> </html>;